def parse_kv(s: str) -> dict:
    result = {}

    def _maybe_int(value: str):
        if not value:
            return value
        start = 1 if value[0] in "+-" else 0
        if start == len(value):
            return value
        if all("0" <= ch <= "9" for ch in value[start:]):
            return int(value)
        return value

    for part in s.split(";"):
        part = part.strip()
        if not part:
            continue
        if "=" not in part:
            raise ValueError(f"Invalid key-value pair: {part!r}")
        key, value = part.split("=", 1)
        key = key.strip()
        value = value.strip()
        result[key] = _maybe_int(value)

    return result
```

