def balanced(s: str) -> bool:
    stack = []
    in_quote = None
    matching = {")": "(", "]": "[", "}": "{"}

    for ch in s:
        if in_quote is not None:
            if ch == in_quote:
                in_quote = None
            continue

        if ch in "'\"":
            in_quote = ch
        elif ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

    return not stack
```

