import threading


class Counter:
    def __init__(self):
        self.n = 0
        self._lock = threading.Lock()

    def add(self, n=1):
        with self._lock:
            self.n += n

    def value(self) -> int:
        with self._lock:
            return self.n

    def reset(self) -> None:
        with self._lock:
            self.n = 0
